    job_id: JobId = Field(description="AblationKit job identifier.")
    project_id: ProjectId = Field(
        description="Stable project identifier (lowercase slug). Never a path; paths live in the local registry."
    )
    command: Annotated[
        list[Annotated[str, StringConstraints(max_length=8192)]],
        Field(min_length=1, max_length=1024),
    ] = Field(description="argv, run from `cwd` inside the project checkout.")
    cwd: (
        Annotated[str, StringConstraints(pattern="^[^/].*$", min_length=1, max_length=1024)] | None
    ) = Field(default=None, description="Working directory relative to the checkout.")
    environment: Literal["uv", "none"] = Field(
        description="`uv`: run through `uv run --frozen --project <checkout>` (the project's own environment). `none`: run argv as given."
    )
    env: dict[str, Annotated[str, StringConstraints(max_length=32768)]] = Field(
        description="Extra environment variables. Stored in plain text: never put secrets here."
    )
    limits: JobLimits = Field(description="CPU, memory, time and task limits for one attempt.")
    artifact_paths: Annotated[
        list[Annotated[str, StringConstraints(min_length=1, max_length=1024)]], Field(max_length=64)
    ] = Field(
        description="Globs relative to the checkout, collected as artifacts after the process exits (for scripts without the SDK)."
    )
    metrics_file: (
        Annotated[str, StringConstraints(pattern="^[^/].*$", min_length=1, max_length=1024)] | None
    ) = Field(
        default=None,
        description="File adapter for scripts without the SDK: a JSON-lines file (relative to the checkout) the collector tails; each object's numeric fields (nested ones flattened with `/`) become metrics at its step.",
    )
    metrics_format: MetricsFormat | None = Field(
        default=None,
        description="How the metrics-file adapter reads each line: nested objects are always flattened with `/`; these name the step and time keys, which are never metrics.",
    )
    input_paths: (
        Annotated[
            list[Annotated[str, StringConstraints(min_length=1, max_length=1024)]],
            Field(max_length=16),
        ]
        | None
    ) = Field(
        default=None,
        description="Globs relative to the checkout, recorded as `inputs/<path>` artifacts as the job starts (configs the source commit does not hold, e.g. ignored ones). Jobs on this machine only.",
    )
    run_name: Annotated[str, StringConstraints(min_length=1, max_length=250)] | None = Field(
        default=None
    )
    description: Annotated[str, StringConstraints(min_length=1, max_length=2000)] | None = Field(
        default=None,
        description="What the run tests and why, in a sentence or two. Each attempt's run starts with it as its summary (ADR 0048).",
    )
    study_id: StudyId | None = Field(
        default=None, description="Study identifier (a planned comparison: baseline plus variants)."
    )
    variant_id: VariantId | None = Field(
        default=None,
        description="Variant identifier (one configuration or code change under test).",
    )
    task_id: TaskId | None = Field(
        default=None, description="AblationKit task identifier (UI- or agent-first task)."
    )
    agenda_item: (
        Annotated[str, StringConstraints(pattern="^(note:[a-z0-9][a-z0-9-]{0,95}|L[0-9]{1,6})$")]
        | None
    ) = Field(
        default=None,
        description="The item of the researcher's agenda this job serves (ADR 0058): `note:<id>` or `L<n>`.",
    )
    mlproject: MlprojectRunInfo | None = Field(
        default=None,
        description="The `MLproject` entrypoint a job was launched from (spec §5.5 MLflow Projects). It runs with local environment semantics in the job runner.",
    )
    target_id: TargetId | None = Field(
        default=None,
        description="Remote compute target (ADR 0023). Absent: this machine. Each attempt runs from its own staged bundle.",
    )
    bundle_inputs: Annotated[list[BundleInput], Field(max_length=8)] | None = Field(
        default=None,
        description="Remote jobs: coordinator-staged directories copied into each attempt's bundle at `inputs/<name>` and checksummed with it (a remote evaluation's pinned model). The job finds them under `$ABLATIONKIT_BUNDLE_INPUTS`.",
    )
    submitted_by: JobActor = Field(description="Who submitted a job.")
    compute_weight_hundredths: Annotated[int, Field(ge=1, le=100000)] | None = Field(
        default=None,
        description="Agent jobs (ADR 0037): the weight of the job's target when it was submitted, in hundredths. Every attempt's wall time times this weight counts against the project's `compute.limit_hours`; changing the target's weight later does not change it.",
    )
    via_extension: Annotated[str, StringConstraints(pattern="^[a-z][a-z0-9-]{1,63}$")] | None = (
        Field(
            default=None,
            description="Submitted through this extension backend's broker (`compute.remote`, ADR 0024); only it may read or cancel the job there.",
        )
    )
    container: JobContainer | None = Field(
        default=None,
        description="Set on jobs a contained agent session submits (ADR 0061): each local attempt runs in a job container of its own.",
    )
    placement: JobPlacement | None = Field(
        default=None,
        description="An agent's job is placed by AblationKit, never by the agent (ADR 0068): queued until a target in the project's pool (this machine if the policy allows local jobs, then the remote targets it allows) has a free slot, then started there.",
    )
    source: JobSource | None = Field(
        default=None,
        description="An agent's job runs its checkout as it was when submitted (ADR 0068): the files Git tracks or would track, with the ignored ones `input_paths` names, copied to `jobs/<job>/source/` and run wherever the job is placed. Hidden paths and `.ablationkit/` are left out.",
    )
    inputs: Annotated[list[JobInput], Field(max_length=8)] | None = Field(default=None)
    gpu: Literal["none"] | None = Field(
        default=None,
        description="The job asked for no GPU (ADR 0066). In a job container it gets no GPU device; on this machine outside one, `CUDA_VISIBLE_DEVICES` is empty (advisory).",
    )
    state: JobState = Field(
        description="State of the latest attempt, or `queued` before the first."
    )
    attempts: list[AttemptId] = Field(description="Attempt IDs, oldest first.")
    created_at: Timestamp = Field(
        description="RFC 3339 timestamp in UTC with a `Z` suffix and optional fractional seconds."
    )
    updated_at: Timestamp = Field(
        description="RFC 3339 timestamp in UTC with a `Z` suffix and optional fractional seconds."
    )


