class WorkerHandshake(ProtocolModel):
    """Reconnection handshake and heartbeat from a remote worker (spec §5.3)."""

    schema_version: Annotated[Literal[1], BeforeValidator(reject_bool)]
    worker_id: Annotated[str, StringConstraints(pattern="^w-[a-f0-9]{8,32}$")]
    hostname: Annotated[str, StringConstraints(max_length=253)]
